def read(name):return json.loads(Path('reports',name+'.json').read_text())
def pair(r):
    x=r['pairs'];n=sum(q['removed_n']for q in x);return dict(n=n,fpr=sum(q['removed_fp']for q in x)/n if n else None)
def main():
    out=Path('reports/m5i_acceptance.json')
    if out.exists():raise FileExistsError(out)
    freeze=verify();train=read('m5i_distillation_comparison');extra=Path('reports/m5i_distillation_comparison_feature.json');tr=train['records']+(json.loads(extra.read_text())['records']if extra.exists()else[]);pix=read('m5i_pixel_test')['records'];teacher=read('m5i_teacher_test')['records'];depth=read('m5i_depth_qualification');bias=read('m5i_depth_bias');shadow=read('m5i_shadow_comparison');lat=read('m5i_inference_latency');coverage=read('m5i_camera_coverage_complete');testcoverage=read('m5i_camera_coverage_test');pp=[]
    for r in pix+teacher:
        q=r['result'];pp.append(dict(name=r['name'],seed=r['seed'],threshold=q['threshold'],metrics=q['metrics'],removed=pair(q),supported=r['supported']['metrics'],supported_removed=pair(r['supported']),actors=dict(miss_rate=q['actor_miss_rate'],observable_views=q['observable_actor_views']),false_components=sum(x['false_components']for x in q['false_detection_components']),fp_per_million=q['false_foreground_per_million_valid_pixels'],unknown=q['unknown_response'],by_scene=q['by_scene'],strata=q['strata'],lowFPR=q['low_fpr_locked_evaluation'],classes={k:v['metrics']for k,v in r['classes'].items()}))
