    bb=[r for r in paired if r['name']=='mobile_gt'];mobile_better=all(r['precision_delta']>0 and r['recall_delta']>0 and r['removed_fpr_delta']<=0 for r in bb);mobile_budget=all(r['p95']<=20 for r in lat['records']if r['name'].startswith('mobile_gt'));stable_kd=any(all(r['precision_delta']>0 and r['recall_delta']>0 and r['removed_fpr_delta']<=0 for r in paired if r['name']==n)for n in ['output_kd','feature_kd']if any(r['name']==n for r in paired));mobile_records=[r for r in tr if r['name']=='mobile_gt'];atomic_json('reports/m5i_lightweight_backbone.json',dict(kind='actual_architecture_control_summary',provenance=read('m5i_pretrained_provenance'),training=mobile_records,paired_test=bb,conditional_feature_executed=extra.exists(),latency=[r for r in lat['records']if r['name'].startswith('mobile_gt')],stable_pooled_better_than_A=mobile_better,budget_passed=mobile_budget,default_encoder_changed=False,limits='FrozenImageNetMobilefeatures vsCARLAadaptedImageNetResNetfeatures; FPNrandom vsM4FPN; architectural/pretraining differences notsinglevariable. No fullyfinetunedMobile capacityclaim.'))
    ss=[]
    for seed in [101,102]:
        for mode in sorted({r['mode']for r in shadow['records']}):
            rr=[r for r in shadow['records']if r['seed']==seed and r['mode']==mode];n=sum(r['matching']['tolerances']['1.0']['gt_count']for r in rr);h=sum(r['matching']['tolerances']['1.0']['matched_gt']for r in rr);tp=sum(r['metrics']['tp']for r in rr);fp=sum(r['metrics']['fp']for r in rr);neg=sum(r['metrics']['negative']for r in rr);ss.append(dict(seed=seed,mode=mode,gt_cells=n,recall_1m=h/n if n else None,precision=tp/(tp+fp)if tp+fp else 0,fpr=fp/neg if neg else None,unknown_high_fraction=float(np.mean([r['unknown_high_fraction']for r in rr]))))
