    atomic_json(out,dict(stage='M5-I',status='Partial',base='4e50203',implementation_commit=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),gates=gates,actual_execution=dict(gpu='RTX4090',pixel_runs=len(tr),steps_per_run=2400,seeds=[101,102],depth_training=False,depth_calibration=False,default_changed=False,visual_control=False),source_sha256=file_hash(__file__)))
    def pct(v):return 'n/a'if v is None else f'{100*v:.2f}%'
    lines=['# M5-I — Reliable Visual Representation Transfer & Depth Qualification','', '**总体 Partial。** 实际完成CARLA支持扩充、RTX4090受控输出迁移与轻量架构对照（特征迁移按预声明条件决定是否执行）、只读Replay Depth资格验证、封存评测和联合Shadow。原默认网络、48LID、HeightSplat、四层BEV、控制器/Physics均未修改。', '', '完整决策见[Architecture Decision Record](../docs/M5I_ARCHITECTURE_DECISION.md)，复现命令见[实现文档](../docs/M5I_IMPLEMENTATION.md)。所有独立状态见`m5i_acceptance.json`。','', '## 基线与控制','', '原ResNet18是官方ImageNet1K V1初始化，再经M4 CARLA训练，并非从零初始化；原权重/Checkpoint/manifest SHA验证通过。M5-H正区KD没有可靠背景监督，原GT高度重叠；Replay整体Bias负向变化已确认。', '', '本轮新增4训练/2验证位置，所有A/B/架构/C使用相同共享数据与1632训练视角的完整首轮曝光采样，同预算2400、种子101/102。A=GT，B=GT+可靠正负软KD，C=GT+独立教师FPN特征（仅B条件失败才执行），Mobile=官方MobileNetV3Large ImageNetV2+GT。未组合多个KD。冻结Backbone缓存减少成本，真实训练的是FPN/PixelHead及C训练适配层；不是完整Backbone微调上限。', '', 'B正类要求可靠GT vehicle/person与教师同意>=.7；负类必须GT可靠非目标且教师<=.05。漏检GT正类、cone、Unknown不作负KD。教师特征256通道经实际resize映射，Student64->256适配层仅训练使用；通道L2归一化余弦，可靠前景/背景/边界均值等权。教师缓存无GT输入。', '', '测试新六位置，Town01两处加Town03/04/05/10HD，每处16配置；Town02无45m隔离候选，Town06本机未安装，地图选择失败日志保留。全新Test在模型/阈值冻结后采集，M5HTest未作选择。', '', '## 二维与架构对照','', '|模型|seed|P|R|AP|背景FPR|Removed局部FPR|Actor-view漏检|','|---|---:|---:|---:|---:|---:|---:|---:|']
    for r in pp:
        m=r['metrics'];lines.append(f"|{r['name']}|{r['seed']}|{pct(m['precision'])}|{pct(m['recall'])}|{pct(m['histogram_ap'])}|{100*(m['fpr']or 0):.5f}%|{pct(r['removed']['fpr'])}|{pct(r['actors']['miss_rate'])}|")
    lines+=['', 'Teacher主行只支持vehicle/person；严格同类Mask比较见supported。主阈值和低FPR工作点仅由Val选择。场景相关性不按百万像素计独立样本。各camera/类别/距离和逐场景曲线在原评测JSON。', '', '## Depth只读资格','', '本轮零Depth训练、零温度/全局Bias校准。固定M5H Replay101 step1000、Replay102 step1200；默认原Head。近场每scene≤1.05×原Head；全局绝对Bias最多比原增0.25m，10–20/20–35段最多增0.5m；空间质量/Oracle投影/远场支持独立验收。','', '|模型|seed|全局MAE m|全局Bias m|近场MAE m|20–35m语义前景MAE / n|20–35m同层1m质量|','|---|---:|---:|---:|---:|---|---:|']
    raw=read('m5i_depth_test')['aggregate']
    for name,seed in [('original',0),('replay',101),('replay',102)]:
        get=lambda sc,di:next(r for r in raw if r['name']==name and r['seed']==seed and r['scope']==sc and r['distance']==di)
        glob=get('all','1.5_80')['metrics'];near=get('all','1.5_10')['metrics'];far=get('actor','20_35');lines.append(f"|{name}|{seed}|{glob['expected_mae']['mean']:.3f}|{glob['signed_bias']['mean']:.3f}|{near['expected_mae']['mean']:.3f}|{far['metrics']['expected_mae']['mean']} / {far['n']}|{pct(far['metrics']['same_layer_1m_mass']['mean'])}|")
    lines+=['', 'Expected MAE为Softmax概率期望光轴深度；Mode/GTBin/层/0.5,1,2m质量/范围外质量分别保存。主表actor scope沿用语义前景Mask；具体Actor关联子集另见`m5i_associated_actor_depth_test.json`，资格额外要求该子集支持与空间质量通过。有效射线去重按sample-camera-UV，仍是相关表面观测，不称统计独立。20–35支持门禁≥100严格射线、≥4位置、≥2类型；缺少任一项不得泛化通过。', '', '资格决定：'+json.dumps(depth['decisions'],ensure_ascii=False)+'。逐场景近场、原S16任务、Bias范围/相机/天气、空间与支持独立原因见`m5i_depth_qualification.json`和`m5i_depth_bias.json`。','', '## BEV联合Shadow','', '|seed|组合|同层1m Recall|可见表面Precision|确认背景FPR|','|---:|---|---:|---:|---:|']
    for r in ss:lines.append(f"|{r['seed']}|{r['mode']}|{pct(r['recall_1m'])}|{pct(r['precision'])}|{pct(r['fpr'])}|")
